package io.github.cakeysama.ultraloot.client.screen;

import com.mojang.blaze3d.systems.RenderSystem;
import io.github.cakeysama.ultraloot.UltraLoot;
import io.github.cakeysama.ultraloot.loot.LootFilter;
import io.github.cakeysama.ultraloot.machine.MachineFamily;
import io.github.cakeysama.ultraloot.upgrade.UpgradeType;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.resources.ResourceLocation;

/**
 * Atlas coordinates of the GUI sheets generated by {@code tools/generate_gui_textures.py}. Both files are 256x256;
 * keep the two in sync.
 */
public final class GuiSprites {
    public static final ResourceLocation WIDGETS = UltraLoot.id("textures/gui/widgets.png");

    public record Sprite(int u, int v, int width, int height) {
        public void draw(GuiGraphics graphics, int x, int y) {
            blit(graphics, x, y, u, v, width, height);
        }

        /** Draws the bottom {@code filled} pixels (vertical bars that fill upwards). */
        public void drawBottom(GuiGraphics graphics, int x, int y, int filled) {
            int h = Math.clamp(filled, 0, height);
            if (h > 0) blit(graphics, x, y + height - h, u, v + height - h, width, h);
        }

        /** Draws the left {@code filled} pixels (horizontal bars that fill rightwards). */
        public void drawLeft(GuiGraphics graphics, int x, int y, int filled) {
            int w = Math.clamp(filled, 0, width);
            if (w > 0) blit(graphics, x, y, u, v, w, height);
        }
    }

    public static final Sprite SLOT = new Sprite(0, 0, 18, 18);
    public static final Sprite SIDE_OVERLAY = new Sprite(20, 0, 18, 18);
    public static final Sprite SIDE_HOVER = new Sprite(40, 0, 18, 18);
    public static final Sprite TAB = new Sprite(0, 20, 24, 22);
    public static final Sprite TAB_SELECTED = new Sprite(26, 20, 30, 22);
    public static final Sprite BAR_FRAME = new Sprite(0, 44, 14, 88);
    public static final Sprite ENERGY_FILL = new Sprite(16, 45, 12, 86);
    public static final Sprite XP_FILL = new Sprite(30, 45, 12, 86);
    public static final Sprite PROGRESS_LOOT = new Sprite(48, 44, 128, 7);
    public static final Sprite PROGRESS_MOB = new Sprite(48, 52, 128, 7);

    /** Button backgrounds, 128x16, drawn in two halves for any width up to 128. */
    public static final int BUTTON_U = 0;
    public static final int BUTTON_V = 136;
    public static final int BUTTON_WIDTH = 128;
    public static final int BUTTON_HEIGHT = 16;

    public enum ButtonState { NORMAL, HOVER, DISABLED, SELECTED }

    public static final Sprite THUMB = new Sprite(130, 136, 8, 15);
    public static final Sprite THUMB_HOVER = new Sprite(140, 136, 8, 15);
    public static final Sprite THUMB_DISABLED = new Sprite(150, 136, 8, 15);

    // Tab icons, 16x16 at v=200.
    public static final Sprite ICON_OVERVIEW = tabIcon(0);
    public static final Sprite ICON_UPGRADES = tabIcon(1);
    public static final Sprite ICON_LOOT = tabIcon(2);
    public static final Sprite ICON_SCAN = tabIcon(3);
    public static final Sprite ICON_SIDES = tabIcon(4);
    public static final Sprite ICON_STATS = tabIcon(5);
    public static final Sprite ICON_MOB = tabIcon(6);
    public static final Sprite ICON_INVENTORY = tabIcon(7);

    // Empty-slot hints, 16x16 at v=216.
    public static final Sprite GHOST_XP = new Sprite(5 * 16, 216, 16, 16);
    public static final Sprite GHOST_MOB_CARD = new Sprite(6 * 16, 216, 16, 16);

    // Small icons, 12x12 at v=232.
    public static final Sprite LOCK = smallIcon(4);

    private GuiSprites() {}

    public static ResourceLocation panel(MachineFamily family) {
        return UltraLoot.id("textures/gui/" + family.id() + ".png");
    }

    public static Sprite ghost(UpgradeType type) {
        return new Sprite(type.ordinal() * 16, 216, 16, 16);
    }

    public static Sprite filterIcon(LootFilter filter) {
        return smallIcon(filter.ordinal());
    }

    public static void button(GuiGraphics graphics, int x, int y, int width, ButtonState state) {
        int v = BUTTON_V + state.ordinal() * BUTTON_HEIGHT;
        int left = width / 2;
        int right = width - left;
        blit(graphics, x, y, BUTTON_U, v, left, BUTTON_HEIGHT);
        blit(graphics, x + left, y, BUTTON_U + BUTTON_WIDTH - right, v, right, BUTTON_HEIGHT);
    }

    /**
     * Plain {@link GuiGraphics#blit} does not enable blending and every {@code fill} disables it again, so the
     * translucent pixels of the sheet (ghost icons, side overlay) need it switched on per draw.
     */
    private static void blit(GuiGraphics graphics, int x, int y, int u, int v, int width, int height) {
        RenderSystem.enableBlend();
        RenderSystem.defaultBlendFunc();
        graphics.blit(WIDGETS, x, y, u, v, width, height);
        RenderSystem.disableBlend();
    }

    private static Sprite tabIcon(int index) {
        return new Sprite(index * 16, 200, 16, 16);
    }

    private static Sprite smallIcon(int index) {
        return new Sprite(index * 12, 232, 12, 12);
    }
}
